import{_ as s,H as e,f as n,i as t}from"./chunks/framework.BH2BK_3i.js";const d=JSON.parse('{"title":"答疑（一）-第1~5讲思考题答案","description":"","frontmatter":{},"headers":[{"level":2,"title":"01 讲的答疑","slug":"_01-讲的答疑","link":"#_01-讲的答疑","children":[{"level":3,"title":"思考题","slug":"思考题","link":"#思考题","children":[]},{"level":3,"title":"答案","slug":"答案","link":"#答案","children":[]}]},{"level":2,"title":"02 讲的答疑","slug":"_02-讲的答疑","link":"#_02-讲的答疑","children":[{"level":3,"title":"思考题","slug":"思考题-1","link":"#思考题-1","children":[]},{"level":3,"title":"答案","slug":"答案-1","link":"#答案-1","children":[]}]},{"level":2,"title":"03 讲的答疑","slug":"_03-讲的答疑","link":"#_03-讲的答疑","children":[{"level":3,"title":"思考题","slug":"思考题-2","link":"#思考题-2","children":[]},{"level":3,"title":"答案","slug":"答案-2","link":"#答案-2","children":[]}]},{"level":2,"title":"04 讲的答疑","slug":"_04-讲的答疑","link":"#_04-讲的答疑","children":[{"level":3,"title":"思考题","slug":"思考题-3","link":"#思考题-3","children":[]},{"level":3,"title":"答案","slug":"答案-3","link":"#答案-3","children":[]}]},{"level":2,"title":"05 讲的答疑","slug":"_05-讲的答疑","link":"#_05-讲的答疑","children":[{"level":3,"title":"思考题","slug":"思考题-4","link":"#思考题-4","children":[]},{"level":3,"title":"答案","slug":"答案-4","link":"#答案-4","children":[]}]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]}],"relativePath":"网络排查案例课/答疑（一）-第1~5讲思考题答案.md","filePath":"网络排查案例课/答疑（一）-第1~5讲思考题答案.md","lastUpdated":1795563497000}'),i={name:"网络排查案例课/答疑（一）-第1~5讲思考题答案.md"};function p(l,a,E,o,c,r){return e(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="答疑-一-第1-5讲思考题答案" tabindex="-1">答疑（一）-第1~5讲思考题答案 <a class="header-anchor" href="#答疑-一-第1-5讲思考题答案" aria-label="Permalink to &quot;答疑（一）-第1~5讲思考题答案&quot;">​</a></h1><p>你好，我是胜辉。</p><p>不知不觉，咱们已经完成预习篇、实战一的 TCP 真实案例篇，还有实战二的应用层真实案例篇的学习了。一路走来，我自己完成了 20 多讲的备课，过程中是辛劳和满足相伴。当然你也很不容易，坚持学完 20 多讲，一共投入的时间也接近 20 个小时，这个过程本身就是一种小小的成就。</p><p>由于课程涉及的网络知识面还是比较广泛的，如果你还有不少没看懂的地方，也别着急，这是很正常的情况。就我自己来说，最初看那些 TCP/IP 概念的时候也是摸不到头脑，后来我就是反复看，从不同的资料、不同的案例来入手，才逐步建立起自己的理解。</p><p>正因为通过问题来理解概念是一种很好的学习方法，所以我在每节课的后面，都留有一两个思考题，希望可以促进思考。这些问题，有些比较容易，有些可能略有难度。所以我整理了答疑篇，一方面给出答案供你参考，一方面也正好把课程里没有覆盖到的细节给你展开一下，作为内容上的补充。总之，我希望通过这个答疑环节，能帮助你把看过的知识都真的消化掉，成为你自己知识体系的一部分。</p><h2 id="_01-讲的答疑" tabindex="-1">01 讲的答疑 <a class="header-anchor" href="#_01-讲的答疑" aria-label="Permalink to &quot;01 讲的答疑&quot;">​</a></h2><h3 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h3><ol><li><p>traceroute 默认是用 UDP 来做探测的，那这个又是基于什么原理呢？通和不通，我们会收到怎样的回复？</p></li><li><p>有时候运行 telnet 后命令就挂起，没有响应了，这说明了什么问题呢？</p></li></ol><h3 id="答案" tabindex="-1">答案 <a class="header-anchor" href="#答案" aria-label="Permalink to &quot;答案&quot;">​</a></h3><p>关于第一个问题，我看到很多同学的回答都已经很到位了，比如以 @webmin 同学的回答为例：</p><ul><li>traceroute 使用 UDP 探测时，初始时把 TTL 设置为 1，经过路由器时 TTL 会被减 1，当TTL 变为 0 时，包被丢弃，路由器向源地址发回一个 ICMP 超时通知（ICMP TimeExceeded Message）。源收到这个通知，就会把下一次发送的包的 TTL 在原来的基础加1，这样就可以多前进一步。探测时使用了一个大于 30000 的端口号去连接，随着 TTL 的增加端口也会加 1，目地服务器在收到这个数据包的时候，会返回一个端口不可达的 ICMP错误信息（ICMP Port Unreachable），当源地址收到 ICMP Port Unreachable 包时，会停止 traceroute。</li></ul><p>在我的 Ubuntu 虚拟机上，traceroute 使用的起始 UDP 目的端口是 33434，然后每次探测的TTL 加一的同时，UDP 目的端口也加一，每次探测会发送 3 次探测报文。也就是下图这样：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%2588%25E4%25B8%2580%25EF%25BC%2589-%25E7%25AC%25AC1~5%25E8%25AE%25B2%25E6%2580%259D%25E8%2580%2583%25E9%25A2%2598%25E7%25AD%2594%25E6%25A1%2588/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%2588%25E4%25B8%2580%25EF%25BC%2589-%25E7%25AC%25AC1~5%25E8%25AE%25B2%25E6%2580%259D%25E8%2580%2583%25E9%25A2%2598%25E7%25AD%2594%25E6%25A1%2588/1.png" alt=""></a></p><p>当时的 traceroute 命令行的输出是这样的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>traceroute www.baidu.com</span></span>
<span class="line"><span>traceroute to www.a.shifen.com (180.101.49.11), 64 hops max</span></span>
<span class="line"><span> 1   10.0.2.2  0.082ms  0.177ms  0.088ms</span></span>
<span class="line"><span> 2   192.168.1.1  4.634ms  1.811ms  1.488ms</span></span>
<span class="line"><span> 3   100.65.0.1  9.972ms  11.511ms  6.189ms</span></span>
<span class="line"><span> 4   61.152.54.125  16.296ms  3.576ms  4.095ms</span></span>
<span class="line"><span> 5   61.152.24.102  7.329ms  6.786ms  11.987ms</span></span>
<span class="line"><span> 6   202.97.71.6  28.938ms  10.568ms  10.069ms</span></span>
<span class="line"><span> 7   58.213.95.2  15.036ms  9.831ms  17.043ms</span></span>
<span class="line"><span> 8   *  *  *</span></span>
<span class="line"><span> 9   58.213.96.54  16.843ms  10.329ms  15.989ms</span></span>
<span class="line"><span>10   *  *  *</span></span>
<span class="line"><span>11   *  *  *</span></span>
<span class="line"><span>12   *  *  *</span></span>
<span class="line"><span>13   *  *  *</span></span>
<span class="line"><span>14   *  *  *</span></span>
<span class="line"><span>15   *  *  *</span></span>
<span class="line"><span>16   *  *  *</span></span></code></pre></div><p>这次 traceroute 没有停住，而是一直到 64 跳的限制后才停止（因为输出过长，我没有把全部</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>的信息复制过来）。当然，一般实践中你看到连续六七个以上的*，基本就可以判定是目的端</span></span></code></pre></div><p>对 UDP 无响应，可以按下 Ctrl + C 终止了。</p><p>我把整个流程的实现原理，概括成了下面的示意图，希望能帮助你理解：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%2588%25E4%25B8%2580%25EF%25BC%2589-%25E7%25AC%25AC1~5%25E8%25AE%25B2%25E6%2580%259D%25E8%2580%2583%25E9%25A2%2598%25E7%25AD%2594%25E6%25A1%2588/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%2588%25E4%25B8%2580%25EF%25BC%2589-%25E7%25AC%25AC1~5%25E8%25AE%25B2%25E6%2580%259D%25E8%2580%2583%25E9%25A2%2598%25E7%25AD%2594%25E6%25A1%2588/2.png" alt=""></a></p><p>然后，我们再用 ICMP 模式做一次 traceroute，输出如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ traceroute -I www.baidu.com</span></span>
<span class="line"><span>traceroute to www.a.shifen.com (180.101.49.12), 64 hops max</span></span>
<span class="line"><span> 1   10.0.2.2  0.105ms  0.229ms  0.173ms</span></span>
<span class="line"><span> 2   192.168.1.1  8.972ms  1.725ms  1.326ms</span></span>
<span class="line"><span> 3   100.65.0.1  9.850ms  7.893ms  7.311ms</span></span>
<span class="line"><span> 4   *  *  61.152.53.149  5.579ms</span></span>
<span class="line"><span> 5   *  61.152.25.230  20.238ms  5.204ms</span></span>
<span class="line"><span> 6   *  *  *</span></span>
<span class="line"><span> 7   *  58.213.94.114  21.249ms  *</span></span>
<span class="line"><span> 8   58.213.94.126  13.869ms  *  *</span></span>
<span class="line"><span> 9   58.213.96.54  11.736ms  10.094ms  10.644ms</span></span>
<span class="line"><span>10   *  *  *</span></span>
<span class="line"><span>11   *  *  *</span></span>
<span class="line"><span>12   *  *  *</span></span>
<span class="line"><span>13   180.101.49.12  24.780ms  9.443ms  10.201ms</span></span></code></pre></div><p>这次就能顺利完成了，这是因为目的 IP 对 ICMP 是有回复的，所以 traceroute 就在最后一跳，也就是第 13 跳顺利停止了。</p><p>这里还有个小技巧。你有没有发现 UDP 和 ICMP 这两种模式下，路径信息是可以互补的？比如 UDP 模式下没有显示第 5 和第 7 跳的 IP，但是 ICMP 模式下就有。这就是为什么我建议你把两种模式分别跑一下，这样可以获取到尽可能完整的路径。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%2588%25E4%25B8%2580%25EF%25BC%2589-%25E7%25AC%25AC1~5%25E8%25AE%25B2%25E6%2580%259D%25E8%2580%2583%25E9%25A2%2598%25E7%25AD%2594%25E6%25A1%2588/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%2588%25E4%25B8%2580%25EF%25BC%2589-%25E7%25AC%25AC1~5%25E8%25AE%25B2%25E6%2580%259D%25E8%2580%2583%25E9%25A2%2598%25E7%25AD%2594%25E6%25A1%2588/3.png" alt=""></a></p><p>第二个问题是关于 telnet 挂起。这里说的“挂起”，是指没有进一步的反应了，比如像下图这样：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%2588%25E4%25B8%2580%25EF%25BC%2589-%25E7%25AC%25AC1~5%25E8%25AE%25B2%25E6%2580%259D%25E8%2580%2583%25E9%25A2%2598%25E7%25AD%2594%25E6%25A1%2588/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%2588%25E4%25B8%2580%25EF%25BC%2589-%25E7%25AC%25AC1~5%25E8%25AE%25B2%25E6%2580%259D%25E8%2580%2583%25E9%25A2%2598%25E7%25AD%2594%25E6%25A1%2588/4.png" alt=""></a></p><p>究其原因，就是 telnet 发送了 SYN 后没有收到 SYN+ACK。我们在第 21 讲提到了系统调用，那么对于 telnet 这样的用户空间程序来说，它要发起 TCP 连接，就必须调用 connect()这个系统调用，后者会负责发出 SYN。但是 SYN 发出去后，对端没有回复 SYN+ACK，这就导致 connect() 阻塞，telnet 程序也只好等在那里，表象上就是挂起了。</p><p>你可以参考这个示意图来理解整个过程：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%2588%25E4%25B8%2580%25EF%25BC%2589-%25E7%25AC%25AC1~5%25E8%25AE%25B2%25E6%2580%259D%25E8%2580%2583%25E9%25A2%2598%25E7%25AD%2594%25E6%25A1%2588/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%2588%25E4%25B8%2580%25EF%25BC%2589-%25E7%25AC%25AC1~5%25E8%25AE%25B2%25E6%2580%259D%25E8%2580%2583%25E9%25A2%2598%25E7%25AD%2594%25E6%25A1%2588/5.png" alt=""></a></p><p>当然，在第 21 讲我们也学习过 strace 这个工具了，所以我们可以用 strace 来验证这个过程。直接运行下面的命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>strace telnet www.baidu.com 500</span></span></code></pre></div><p>就能看到，strace 停留在 connect() 系统调用这里了：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>......</span></span>
<span class="line"><span>socket(AF_INET, SOCK_STREAM, IPPROTO_IP) = 3</span></span>
<span class="line"><span>setsockopt(3, SOL_IP, IP_TOS, [16], 4)  = 0</span></span>
<span class="line"><span>connect(3, {sa_family=AF_INET, sin_port=htons(500), sin_addr=inet_addr(&quot;45.113.19</span></span></code></pre></div><h2 id="_02-讲的答疑" tabindex="-1">02 讲的答疑 <a class="header-anchor" href="#_02-讲的答疑" aria-label="Permalink to &quot;02 讲的答疑&quot;">​</a></h2><h3 id="思考题-1" tabindex="-1">思考题 <a class="header-anchor" href="#思考题-1" aria-label="Permalink to &quot;思考题&quot;">​</a></h3><ol><li><p>请你用偏移量方法，写一个 tcpdump 抓取 TCP SYN 包的过滤表达式。</p></li><li><p>如果确定问题是在 IP 层，tcpdump 命令如何写，可以做到既找到 IP 层的问题，又节约抓包文件大小呢？</p></li></ol><h3 id="答案-1" tabindex="-1">答案 <a class="header-anchor" href="#答案-1" aria-label="Permalink to &quot;答案&quot;">​</a></h3><p>很多同学都写出了正确的偏移量的过滤表达式，也就是：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tcpdump &#39;tcp[13]&amp;2 != 0&#39;</span></span></code></pre></div><p>当然，这个题目没有指明是一定只要 SYN 包，我们用上面这条命令可以抓到 SYN 和SYN+ACK 这两种报文。而如果要指定只抓取 SYN 包而不抓取 SYN+ACK，可以用下面的表达式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tcpdump &#39;tcp[13]|2 = 2&#39;</span></span>
<span class="line"><span>注意：这里的运算符是“|”，也就是字符或运算符。</span></span></code></pre></div><p>第二个问题的关键点是 tcpdump 的 -s 参数，我们通过它可以指定要抓取的每个报文的大小。不过那就有个问题了，这里的“报文”是指 IP 分组还是二层帧呢？</p><p>虽然 tcpdump 名称里是 tcp，实际上它能抓取 udp、ip、icmp 等等各种报文，因为它抓取的就是第二层的帧。所以说，这里的“报文大小”，指的是二层帧的大小。我在第 2 讲里也贴了一张图，展示了在某一次抓包里，一个报文的各层占用的字节数：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%2588%25E4%25B8%2580%25EF%25BC%2589-%25E7%25AC%25AC1~5%25E8%25AE%25B2%25E6%2580%259D%25E8%2580%2583%25E9%25A2%2598%25E7%25AD%2594%25E6%25A1%2588/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%2588%25E4%25B8%2580%25EF%25BC%2589-%25E7%25AC%25AC1~5%25E8%25AE%25B2%25E6%2580%259D%25E8%2580%2583%25E9%25A2%2598%25E7%25AD%2594%25E6%25A1%2588/6.png" alt=""></a></p><p>一般来说，IP 头部就是 20 字节，加上帧头 14 字节，所以理论上我们只要抓取前 34 字节的报文，就可以获取到二层和三层的信息了。</p><p>不过且慢，有个同学报告了一个问题：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>老师，对于“问题 2”我有个疑问。我最开始用的命令是“tcpdump -i any -s 34”，发现 -</span></span></code></pre></div><ul><li>s 写成 34，就抓不到网络层的目的地址字段，用 Wireshark 分析后发现，帧头（不知道还</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>叫不叫这个，Wireshark 显示为 Linux cooked capture v1）占了 16 个字节，写成</span></span>
<span class="line"><span>36 就能把信息抓全了，但是写成“tcpdump -i eth0 -s 34”就可以抓全。</span></span></code></pre></div><p>这个问题我之前也没留意到，于是去查证了一下。原来在 tcpdump 里，对于 any 这个接口，它在输出帧头的时候用了一种叫 Linux cooked capture v1 的格式，这个格式的长度是 16 个字节，而以太网帧是 14 字节。这就造成了 2 个字节的差异，也就是按原先的 34 字节去抓取就不够了，所以要扩大到 36 字节才可以抓到完整的 IP 头部。</p><p>我们看一个例子：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%2588%25E4%25B8%2580%25EF%25BC%2589-%25E7%25AC%25AC1~5%25E8%25AE%25B2%25E6%2580%259D%25E8%2580%2583%25E9%25A2%2598%25E7%25AD%2594%25E6%25A1%2588/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%2588%25E4%25B8%2580%25EF%25BC%2589-%25E7%25AC%25AC1~5%25E8%25AE%25B2%25E6%2580%259D%25E8%2580%2583%25E9%25A2%2598%25E7%25AD%2594%25E6%25A1%2588/7.png" alt=""></a></p><ul><li>补充：上面的 traceroute udp 模式的示例文件就是用 -i any 模式抓取的，所以它的二层帧</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>头就是 Linux cooked capture v1 格式。</span></span></code></pre></div><p>另外，“IP 头部 20 字节”这个描述，其实还有一个隐含的前提：IP 头部没有做扩展（Options）。跟 TCP 类似，IP 头部也可以扩展，但是一般用的比较少，在公网上 IP Options的报文有可能被丢弃，所以很少被采用。我们在内网也曾经做过实验，启用了 IP Options，结果发现虽然内网设备可以支持 IP Options，但是延迟增加了很多，所以最后还是取消了它。</p><h2 id="_03-讲的答疑" tabindex="-1">03 讲的答疑 <a class="header-anchor" href="#_03-讲的答疑" aria-label="Permalink to &quot;03 讲的答疑&quot;">​</a></h2><h3 id="思考题-2" tabindex="-1">思考题 <a class="header-anchor" href="#思考题-2" aria-label="Permalink to &quot;思考题&quot;">​</a></h3><ol><li><p>在 Linux 中，还有一个内核参数也是关于握手的，net.ipv4.tcp_synack_retries。你知道这个参数是用来做什么的吗？</p></li><li><p>如果握手双方，一方支持 Window Scale，一方不支持，那么在这个连接里，Window Scale最终会被启用吗？你可以参考RFC1323，给出你的解答。</p></li></ol><h3 id="答案-2" tabindex="-1">答案 <a class="header-anchor" href="#答案-2" aria-label="Permalink to &quot;答案&quot;">​</a></h3><p>第一个问题是关于 Linux 内核参数的。对于各种网络相关的内核参数来说，最快捷的方法可能就是直接在 Linux 主机里面查看 TCP 的手册了，也就是执行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>man tcp</span></span></code></pre></div><p>然后搜索 tcp_synack_retries 就可以了，也就是这个部分：</p><ul><li>tcp_synack_retries (integer; default: 5; since Linux 2.2)The maximum number of times a SYN/ACK segment for a passive TCP connection will beretransmitted. This number should not be higher than 255.</li></ul><p>也就说，这是 TCP 回复 SYN+ACK 后等不到 ACK 时，需要重试的次数。</p><p>第二个问题是关于 Window Scale（下面简称 WS）在握手中的具体实现。就像我题目里说的，你可以直接去找到RFC1323，然后找到这部分的内容：</p><ul><li>This option may be sent in an initialsegment (i.e., a segment with the SYN bit on and theACK bit off). It may also be sent in a &lt;​SYN,ACK&gt; segment, but only if a Window Scaleoption was received in the initialsegment. A Window Scale option in a segment without aSYN bit should be ignored.</li></ul><p>直译过来就是：这个 WS 选项可以在 SYN 包中，也可以在 SYN+ACK 包中。但只有收到的SYN 中有这个 WS 选项，回复的 SYN+ACK 才可以加上这个选项。如果收到的报文不带 SYN标志位但却带上了 WS 选项，这样的 WS 应该被忽略。</p><p>也就是说，如果发过来的 SYN 里不带 WS 选项，那回复的 SYN+ACK 也不应该带 WS，自然这次的连接里也就不会用上 WS 了。简单来说，只要有一方不支持 WS，这次的连接里就不会用 WS。</p><h2 id="_04-讲的答疑" tabindex="-1">04 讲的答疑 <a class="header-anchor" href="#_04-讲的答疑" aria-label="Permalink to &quot;04 讲的答疑&quot;">​</a></h2><h3 id="思考题-3" tabindex="-1">思考题 <a class="header-anchor" href="#思考题-3" aria-label="Permalink to &quot;思考题&quot;">​</a></h3><ol><li><p>如果要在 Wireshark 中搜索到挥手阶段出现的 RST+ACK 报文，那么这个过滤器该如何写呢？</p></li><li><p>你有没有通过抓包分析，解决过应用层的奇怪问题呢？你是怎么做的呢？</p></li></ol><h3 id="答案-3" tabindex="-1">答案 <a class="header-anchor" href="#答案-3" aria-label="Permalink to &quot;答案&quot;">​</a></h3><p>第一个问题里挥手阶段出现 RST 的现象， 这个已经不是用 FIN 完成的标准挥手过程了，而是出现了异常。不过从报文特征来说还是比较直接的，就是既要带 RST 标志位，也要带 ACK 标志位，所以答案就是：tcp.flags.ack==1 and tcp.flags.reset == 1。</p><p>第二个问题是开放式的，比如 @江山如画同学分享了一个挺有意思的案例，是双方时钟不同步导致了 TLS 握手失败。时钟问题也是一个挺有“存在感”的问题，时不时会在各种故障中扮演一点角色，我们可以在排查没什么方向的时候，也可以查一下时钟。</p><p>另外说到 TLS 握手的问题，我在第 19 讲里介绍了两个典型案例，也是刚过去不久的一讲，我想你应该还有印象。</p><h2 id="_05-讲的答疑" tabindex="-1">05 讲的答疑 <a class="header-anchor" href="#_05-讲的答疑" aria-label="Permalink to &quot;05 讲的答疑&quot;">​</a></h2><h3 id="思考题-4" tabindex="-1">思考题 <a class="header-anchor" href="#思考题-4" aria-label="Permalink to &quot;思考题&quot;">​</a></h3><p>这节课里，我介绍了使用裸序列号作为定位两侧同个报文的手段。那么要定位两侧的同个报文，除了这个方法，还有哪些方法呢？你可以从网络七层模型出发，给出自己的思考。</p><h3 id="答案-4" tabindex="-1">答案 <a class="header-anchor" href="#答案-4" aria-label="Permalink to &quot;答案&quot;">​</a></h3><p>定位两侧同个报文，是一个比较关键的技术点，因为抓包分析的一个重要任务，就是对比两侧抓包文件中的报文，从而判定丢包、乱序、重传等行为的严重程度和原因，由此才能针对性地做进一步排查乃至找到解决方案。如果不能找到“同个报文”，那刚才说的一系列工作就无从谈起了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%2588%25E4%25B8%2580%25EF%25BC%2589-%25E7%25AC%25AC1~5%25E8%25AE%25B2%25E6%2580%259D%25E8%2580%2583%25E9%25A2%2598%25E7%25AD%2594%25E6%25A1%2588/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%2588%25E4%25B8%2580%25EF%25BC%2589-%25E7%25AC%25AC1~5%25E8%25AE%25B2%25E6%2580%259D%25E8%2580%2583%25E9%25A2%2598%25E7%25AD%2594%25E6%25A1%2588/8.png" alt=""></a></p><ul><li>补充：A 和 B 对报文的编号一般是不同的，因为各自抓取报文的起始时间、抓取条件等都可能不同，就会导致抓取到的报文互有交集。</li></ul><p>比如上面就是一个典型的 TCP 问题的场景，也就是报文顺序发生了变化，这个现象就是“乱序”：发出 1、2、3，收到的却是 2、1、3。那么显然，我们需要在两侧的抓包文件里，找到对应的同个报文。事实上，现在说的 1、2、3，是 A 的抓包文件里的报文编号，而 B 那边有自己的视角和报文编号，跟 A 是完全不同的。</p><p>我在第 5 讲里介绍的方法，是用了裸序列号（原始序列号），因为 TCP 报文的这个序列号在传输中是不会变化的，所以这就是一个很好的确定报文的方法。其实，这属于第一大类方法：按照 TCP 报文的元信息，也就是 TCP 头部的特征去找到对应的报文。</p><p>既然确定了这个大类的方法原则，你很容易举一反三，想到其他的方法。比如：</p><ul><li>用 TCP 确认号，比如下面这个过滤器：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tcp.ack_raw == 754313633</span></span></code></pre></div><ul><li>如果有 TCP timestamp 扩展，就用 TCP timestamp，比如下面两种过滤器：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tcp.options.timestamp.tsval == 2947948748</span></span>
<span class="line"><span>tcp.options.timestamp.tsecr == 3209788920</span></span></code></pre></div><ul><li>如果有 TCP SACK 扩展，就用 SACK 号，比如用过滤器：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tcp.options.sack_le == 1234</span></span></code></pre></div><p>而第二个大类的方法，是利用 TCP 的载荷本身的特征去找到对应的报文。比如 HTTP 是文本协议，那么我们用下面这个过滤器，就可以找到含有这个字符串的报文：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tcp contains &quot;id=abcdafeafeagfeagfaraera1242dfea&quot;</span></span></code></pre></div><p>其实换成以下这几种方式，也是一样的效果：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>frame contains &quot;id=abcdafeafeagfeagfaraera1242dfea&quot;</span></span>
<span class="line"><span>ip contains &quot;id=abcdafeafeagfeagfaraera1242dfea&quot;</span></span>
<span class="line"><span>http contains &quot;id=abcdafeafeagfeagfaraera1242dfea&quot;</span></span></code></pre></div><p>这个示意图，也表示了这样的两大类寻找对应报文的方法：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%2588%25E4%25B8%2580%25EF%25BC%2589-%25E7%25AC%25AC1~5%25E8%25AE%25B2%25E6%2580%259D%25E8%2580%2583%25E9%25A2%2598%25E7%25AD%2594%25E6%25A1%2588/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/%25E7%25AD%2594%25E7%2596%2591%25EF%25BC%2588%25E4%25B8%2580%25EF%25BC%2589-%25E7%25AC%25AC1~5%25E8%25AE%25B2%25E6%2580%259D%25E8%2580%2583%25E9%25A2%2598%25E7%25AD%2594%25E6%25A1%2588/9.png" alt=""></a></p><p>不过，你看了这张图，会不会以为我们每个报文都要这么找对应关系呢？那当然不用了，每个TCP 流只要找一个关键报文，然后根据这个报文去做 Follow -&gt; TCP Stream 就好了。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>以上就是针对课程前 5 讲思考题的参考答案和拓展解读，希望能给你一些启发。另外，也非常感谢你对课后思考题的仔细思考和认真解答。在看留言的过程中，我从大家的答复中也看到了更加全面或是更加深入的思考，我自己受益匪浅。</p><p>接下来，我还会针对剩余的课后思考题，以及你的提问来作出解答。有任何问题，还是跟以前一样，欢迎你在留言区跟我交流，我们一同成长。</p>`,102)])])}const u=s(i,[["render",p]]);export{d as __pageData,u as default};
